 const descriptions:Record<string,string>={checkpoints:'Saved every 30 minutes while the backend runs, or after 5 new prescriptions. Restore any checkpoint and keep a recovery copy.',tools:'Your complete workspace. Choose a tool to get started.',overview:'A clear view of your prescriptions, stock and daily care.',inventory:'Check stock, view batches and add medicines.',search:'Find a patient, medicine, prescription or invoice.',monitor:'Stock, expiry dates, prescriptions and follow-ups that need attention.',medicines:'The formulary, linked batches, and configured stock thresholds.',batches:'Track quantities, expiry dates, prices, and stock held for reviewed requests.',prescriptions:'Prescribing records remain separate from stock dispensing.',verification:'Review uploaded prescriptions and reserve unexpired stock for pickup or delivery.',checkout:'Pick a prescription. Check the medicines. Issue with confidence.',orders:'Draft, send, and receive supplier orders without duplicating stock.',safety:'Patient rules, medicine combinations and dose limits enforced during dispensing. Medicine references are linked below.',followups:'Refill reminders and recorded patient follow-up outcomes.',reports:'Calculated from saved invoices and current stock.',accounts:'Authenticated accounts with permissions enforced by the backend.'};
