 if(route==='prescriptions'||route==='checkout'&&!isStaff)content=<><div className="rx-toolbar">{canPrescribe&&route==='prescriptions'&&button('New prescription',()=>open('prescription'),true)}</div><Table rows={route==='checkout'?pending:rx} search={search} columns={[{label:'Reference',render:r=><RecordPeek row={r} items={(data.prescriptionItems||[]).filter((i:Row)=>i.prescription_id===r.id)} onOpen={()=>open('rx-detail',r)}/>},...cols([['patient_name','Patient'],['doctor_name','Doctor'],['prescription_date','Date']]),statusCol,{label:'',render:r=><div className="rx-actions">{button('Details',()=>open('rx-detail',r))}{isStaff&&(r.status==='In Filling'?button('Dispense',()=>open('checkout',r)):r.status==='Pending Review'?button('Dispense now',async()=>{await perform(()=>api(`/prescriptions/${r.id}/review`,'PATCH',{}),'Prescription marked reviewed.');open('checkout',{...r,status:'In Filling'});}):null)}{isStaff&&r.status==='In Filling'&&(()=>{const action=(data.actions||[]).find((a:Row)=>!a.undone_at&&a.path===`/prescriptions/${r.id}/review`);return button('Undo review',()=>action?undoAction(action):perform(()=>api(`/prescriptions/${r.id}/unreview`,'PATCH',{}),'Prescription returned to pending review.')); })()}</div>}]}/></>;
