 if(!token)return <div className="rx-login rx-view-picker"><div className="rx-login-brand"><span className="dash-login-logo"><Pill size={28}/>PharmRx</span><span className="dash-login-tag">YOUR CONNECTED PHARMACY</span><h1>Good care.<br/>Clear records.<br/><em>One workspace.</em></h1><p>A calmer way to manage your pharmacy, from the first prescription to the next follow-up.</p><div className="dash-login-symbols"><Package/><Plus/><Pill/><Sparkles/></div><small>Clinical pharmacy management · College DBMS project</small></div><div className="rx-login-form"><span className="rx-kicker">WELCOME TO PHARMRX</span><h2>Make room<br/>for better care.</h2><p>Choose your workspace to get started.</p>{error&&<div className="rx-error" role="alert">{error}</div>}<div className="rx-view-options">{[['admin','Admin workspace','Manage records, safety rules, reports and checkpoints.'],['pharmacist','Pharmacist workspace','Review prescriptions, check stock and issue medicines.']].map(([view,title,description],index)=><button key={view} className="rx-view-option" disabled={busy} onClick={()=>enterView(view)}><span className="rx-view-number">{index===0?<LayoutDashboard size={23}/>:<Pill size={23}/>}</span><span><strong>{enteringView===view?'Opening workspace…':title}</strong><small>{description}</small></span><ArrowUpRight size={22}/></button>)}</div><small className="rx-view-caption">College demo · shared workspace views</small></div></div>;
 return <div className="rx-app pw-app" data-theme="black-yellow"><aside className={menu?'open':''}><button className="dash-brand" aria-label="PharmRx dashboard" onClick={()=>{setRoute('overview');setMenu(false);}}><Pill size={25}/></button><nav aria-label="Main navigation">{navigation.map(([id,label])=>{const Icon=navIcons[id]||FileText;return <button key={id} title={label} aria-label={label} className={route===id?'active':''} aria-current={route===id?'page':undefined} onClick={()=>{setRoute(id);setSearch('');setMenu(false);}}><Icon size={21}/><span>{label}</span></button>;})}{extraNavigation.length>0&&<button title="Workspace tools" aria-label="Workspace tools" className={route==='tools'||extraNavigation.some(([id])=>id===route)?'active':''} onClick={()=>{setRoute('tools');setSearch('');setMenu(false);}}><Grid2X2 size={21}/><span>All tools</span></button>}</nav><button className="dash-switch" aria-label="Switch workspace view" title="Switch workspace view" disabled={busy} onClick={switchView}><LogOut size={21}/></button><span className="dash-avatar" title={data?.user?.name||'Workspace'}>{role==='admin'?'AD':'PH'}</span></aside>{menu&&<button aria-label="Close navigation" className="rx-backdrop" onClick={()=>setMenu(false)}/>}<div className="rx-main"><header><button className="rx-mobile-menu rx-icon-button" aria-label="Open navigation" onClick={()=>setMenu(!menu)}><Menu size={20}/></button><span className="rx-kicker">PharmRx <span className="dash-workspace-label">/ {role==='admin'?'Admin':'Pharmacist'} workspace</span></span><div className="rx-header-actions">{loading&&data&&<span className="pw-updating" role="status"><RefreshCw size={13}/>Updating…</span>}<button className="rx-icon-button ap-history-button" title="Saved action history" aria-label="Saved action history" onClick={()=>{setError('');setOlderActions([]);setHistoryEnd(false);setModal({kind:'history'});}}><History size={17}/><span>History</span></button><button className="rx-icon-button ap-undo-button" aria-label="Undo latest saved action" title="Undo latest saved action" disabled={busy||!(data?.actions||[]).some((a:Row)=>!a.undone_at)} onClick={()=>undoAction((data?.actions||[]).find((a:Row)=>!a.undone_at))}><Undo2 size={17}/><span>Undo</span></button>{route!=='search'&&<label className="rx-search"><Search size={15}/><input aria-label="Search current view" placeholder="Search by name or number…" value={search} onChange={e=>setSearch(e.target.value)}/>{search&&<button className="rx-icon-button" aria-label="Clear search" onClick={()=>setSearch('')}><X size={15}/></button>}</label>}<button className="rx-icon-button" title="Refresh records" aria-label="Refresh records" disabled={loading||busy} onClick={()=>load()}><RefreshCw size={16}/></button><button className="rx-icon-button" aria-label="Switch workspace view" title="Switch view" disabled={busy} onClick={switchView}><LogOut size={16}/></button></div></header><main><div className="rx-page-heading"><div><span className="rx-kicker">{day()} · PHARMRX</span><h1>{route==='overview'?<>Managing your pharmacy<br/>and <span className="dash-title-accent"><Sparkles size={26}/></span> daily care.</>:titles[route]||'Workspace'}</h1><p>{descriptions[route]||'Keep records clear, connected, and easy to find.'}</p></div>{isStaff&&<button className="pw-primary dash-heading-action" onClick={()=>open('prescription')}><Plus size={18}/>Add prescription</button>}</div>{isStaff&&<div className="dash-page-tabs" aria-label="Workspace sections">{[['overview','Overview'],['prescriptions','Prescriptions'],['inventory','Inventory'],['patients','Patients'],['invoices','Invoices'],['reports','Reports'],['tools','All tools']].map(([id,label])=><button key={id} aria-current={route===id?'page':undefined} onClick={()=>{setRoute(id);setSearch('');}}>{label}</button>)}</div>}{error&&<div className="rx-error" role="alert">{error}</div>}{notice&&<div className="rx-notice" role="status"><span>{notice}</span>{lastAction&&<button className="ap-toast-undo" disabled={busy} onClick={()=>undoAction(lastAction)}><Undo2 size={16}/>Undo</button>}<button aria-label="Dismiss notice" onClick={()=>setNotice('')}><X size={14}/></button></div>}{loading&&!data?<WorkspaceSkeleton route={route}/>:data?<div className="ap-page-content" key={route}>{content}</div>:<div className="rx-empty">Could not load your workspace. {button('Retry',()=>load())}</div>}</main><footer><Motif/>PharmRx<span>College project · fictional records</span><Motif/></footer></div>
 <SaveFeedback operation={operation} busy={busy} onClose={()=>setOperation(null)} onUndo={()=>{const action=operation?.undo;setOperation(null);if(action)undoAction(action);}}/>{modal&&<div className="rx-modal-overlay" onClick={e=>{if(e.target===e.currentTarget&&!busy)setModal(null);}}><div className={`rx-modal ${['checkout','prescription','verify','receive','invoice'].includes(modal.kind)?`large ${modal.kind==='checkout'?'issue-modal':''}`:''}`} role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="rx-modal-heading"><div><span className="rx-kicker">PHARMRX · RECORD ENTRY</span><h2 id="modal-title">{({flagRules:'Patient flag rule',medicineProfiles:'Medicine dose profile',checkpoint:'Save checkpoint','restore-checkpoint':'Restore checkpoint',prescription:'New prescription',checkout:'Issue medicines',verify:'Verify & reserve stock',upload:'Upload prescription',receive:'Receive purchase order',order:'New purchase order','rx-detail':`Prescription RX-${modal.row?.id}`,invoice:`Invoice INV-${modal.row?.id}`,'upload-detail':'Uploaded prescription','remove-rule':'Remove safety rule',reject:'Reject upload',history:'Saved action history',menu:'More tools'} as Row)[modal.kind]||`${modal.row?'Edit':'Add'} ${modal.kind}`}</h2></div><button type="button" className="rx-icon-button" aria-label="Close dialog" disabled={busy} onClick={()=>setModal(null)}><X size={20}/></button></div>{error&&<div className="rx-error" role="alert">{error}</div>}
 {modal.kind==='menu'?<div className="issue-more-tools">{extraNavigation.map(([id,label])=><button key={id} onClick={()=>{setRoute(id);setSearch('');setModal(null);}}><Motif/>{label}<ArrowRight size={17}/></button>)}</div>:modal.kind==='history'?<><p>Undo your saved changes here, including changes from earlier visits. If a later record depends on an action, undo that later action first.</p><div className="ap-action-history">{[...(data?.actions||[]),...olderActions].map((action:Row)=><div className="ap-history-row" key={action.id}><div><b>{action.label}</b><small>{String(action.created_at).replace('T',' ').slice(0,19)}</small></div>{action.undone_at?<span className="rx-status">Undone</span>:<button className="rx-text-button" disabled={busy} onClick={()=>undoAction(action)}><Undo2 size={15}/>Undo</button>}</div>)}{!(data?.actions||[]).length&&<p>No saved actions yet. Your next save will appear here.</p>}{!historyEnd&&(data?.actions||[]).length===40&&<button className="rx-text-button" disabled={busy} onClick={earlierActions}>Load earlier actions</button>}</div></>:modal.kind==='restore-checkpoint'?<><p>Restore <b>{modal.row.label}</b> from {modal.row.created_at}? This restores stock, prescriptions, invoices and other tracked records for every account. Current records are saved to a recovery checkpoint first.</p><div className="rx-modal-footer">{button('Restore this checkpoint',()=>perform(()=>api(`/checkpoints/${modal.row.id}/restore`,'POST',{}),'Checkpoint restored. Current records were saved in a recovery checkpoint.'),true)}</div></>:modal.kind==='rx-detail'?<><p>{modal.row.patient_name} · {modal.row.doctor_name} · {shortDate(modal.row.prescription_date)} {badge(modal.row.status)}</p><p>{modal.row.notes}</p><Table rows={(data?.prescriptionItems||[]).filter((i:Row)=>i.prescription_id===modal.row.id)} columns={cols([['medicine_name','Medicine'],['dosage','Dosage'],['frequency','Frequency'],['duration_days','Days'],['quantity_prescribed','Quantity']])}/></>:modal.kind==='invoice'?<div className="rx-print-invoice"><div className="rx-invoice-brand">PharmRx · Invoice INV-{modal.row.id}</div><p>{modal.row.patient_name} · {shortDate(modal.row.invoice_date)}<br/>Dispensed by {modal.row.pharmacist_name} · RX-{modal.row.prescription_id}</p><Table rows={(data?.invoiceItems||[]).filter((i:Row)=>i.invoice_id===modal.row.id)} columns={[...cols([['medicine_name','Medicine'],['batch_number','Batch'],['qty_sold','Quantity']]),{label:'Unit price before tax',render:r=>money(r.unit_price)},{label:'Configured GST',render:r=>`${r.tax_rate}%`}]}/><div className="rx-totals"><span>Subtotal <b>{money(modal.row.subtotal)}</b></span><span>CGST <b>{money(modal.row.cgst)}</b></span><span>SGST <b>{money(modal.row.sgst)}</b></span><span className="total">Net payable <b>{money(modal.row.net_payable)}</b></span></div>{modal.row.override_reason&&<p>Warning acknowledgement: {modal.row.override_reason}</p>}<small>Local project invoice. Tax calculated from configured rates; unit prices exclude tax.</small><div className="rx-modal-footer">{button('Print invoice',()=>window.print(),true)}</div></div>:modal.kind==='upload-detail'?<><p>{modal.row.patient_name} · {modal.row.fulfillment_type} {badge(modal.row.verification_status)}</p><img className="rx-prescription-image" src={modal.row.uploaded_image_url} alt="Uploaded prescription"/><p>{modal.row.reviewer_notes||'Awaiting pharmacist review.'}</p></>:modal.kind==='remove-rule'?<><p>This removes the configured rule from future checks. Existing invoices are preserved.</p><div className="rx-modal-footer">{button('Remove rule',()=>perform(()=>api(`/safety/${modal.ruleKind}/${modal.row.id}`,'DELETE')),true)}</div></>:modal.kind==='reject'?<form onSubmit={e=>{e.preventDefault();perform(()=>api(`/verification/${modal.row.id}`,'PATCH',{status:'Rejected',notes:form.notes}),'Request rejected and reserved stock released.');}}><Fields fields={[{key:'notes',label:'Reason',type:'textarea'}]} value={form} onChange={setForm}/><div className="rx-modal-footer"><button className="rx-button" disabled={busy}>Reject and release stock</button></div></form>:<form onSubmit={submit}>
 {modal.kind==='checkout'?<IssueMedicineForm data={data} form={form} setForm={(v:Row)=>{if(v.prescription_id!==form.prescription_id){setPreview(null);setItems(allocate(v.prescription_id));}setForm(v);}} items={items} setItems={setItems} preview={preview} checking={previewBusy} busy={busy} onRetry={getPreview} today={day()}/>:<><Fields fields={definitions[modal.kind]||[]} value={form} onChange={setForm}/>{['prescription','order','upload','verify','receive','interaction'].includes(modal.kind)&&<><h3>{modal.kind==='verify'?'Transcribe and verify the prescription':modal.kind==='receive'?'Received batches':'Medicines'}</h3><Lines items={items} setItems={setItems} medicines={data?.medicines||[]} detailed={['prescription','verify'].includes(modal.kind)} batches={modal.kind==='receive'} fixed={modal.kind==='receive'}/></>}{modal.kind==='upload'&&<label className="rx-file">Prescription image (PNG, JPEG, WebP · maximum 2 MB)<input required type="file" accept="image/png,image/jpeg,image/webp" onChange={e=>fileChanged(e.target.files?.[0])}/>{form.image&&<img className="rx-prescription-image" src={form.image} alt="Prescription preview"/>}<small>Selected medicines are requests; a pharmacist must verify the original prescription before allocation.</small></label>}{modal.kind==='verify'&&<details><summary>View original prescription</summary><img className="rx-prescription-image" src={modal.row.uploaded_image_url} alt="Original uploaded prescription"/></details>}{alertBlock(safetyPreview)}</>}
 <div className="rx-modal-footer"><button type="button" className="rx-text-button" disabled={busy} onClick={()=>setModal(null)}>Cancel</button><button className="rx-button" disabled={busy||modal.kind==='checkout'&&(previewBusy||!preview||preview.alerts.some((a:Row)=>a.severity==='CRITICAL')||preview.alerts.length>0&&(!form.warning_ack||!String(form.override_reason||'').trim())||form.special_case&&!String(form.override_reason||'').trim())||modal.kind==='upload'&&!form.image}>{busy?'Saving…':modal.kind==='checkout'?`Issue medicines${preview?' · '+money(preview.totals.net_payable/100):''}`:modal.kind==='prescription'?'Save & issue medicines':modal.kind==='verify'?'Verify & allocate stock':'Save record'}</button></div></form>}</div></div>}
 </div>;
